import React, { useEffect, useState } from "react";
import { Outlet, Link, useNavigate, useLocation } from "react-router-dom";
import {
  FaBookOpen,
  FaChalkboardTeacher,
  FaUserGraduate,
  FaCalendarAlt,
  FaSignOutAlt,
  FaGraduationCap,
  FaTasks,
  FaClipboardList,
  FaBrain,
  FaFolderOpen,
  FaClock,
  FaBell,
  FaChartLine,
  FaBars
} from "react-icons/fa";
import "./theme.css";

function MainLayout() {
  const navigate = useNavigate();
  const location = useLocation();

  const userName = localStorage.getItem("user_name");
  const role = localStorage.getItem("role");

  const [theme, setTheme] = useState(localStorage.getItem("theme") || "light");
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 900);

  // 🔹 Handle theme
  useEffect(() => {
    document.documentElement.setAttribute("data-theme", theme);
    localStorage.setItem("theme", theme);
  }, [theme]);

  // 🔹 Responsive detection
  useEffect(() => {
    const handleResize = () => {
      const mobile = window.innerWidth < 900;
      setIsMobile(mobile);

      if (mobile) {
        setSidebarOpen(false);
      } else {
        setSidebarOpen(true);
      }
    };

    window.addEventListener("resize", handleResize);
    handleResize();

    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const handleLogout = () => {
    localStorage.clear();
    navigate("/");
  };

  const linkStyle = (path) => {
    const active = location.pathname === path;

    return {
      display: "flex",
      alignItems: "center",
      gap: "12px",
      padding: "12px 14px",
      borderRadius: "14px",
      color: active ? "#fff" : "var(--text)",
      background: active ? "#ffffff10" : "transparent",
      border: active ? "1px solid var(--border)" : "none",
      fontWeight: 700,
      marginBottom: "8px",
      transition: "0.2s"
    };
  };

  return (
    <div style={{ display: "flex", minHeight: "100vh" }}>
      {/* 🔥 Sidebar */}
      <aside
        style={{
          width: isMobile ? "270px" : sidebarOpen ? "280px" : "86px",
          background: "var(--surface)",
          borderRight: "1px solid var(--border)",
          padding: "16px",
          position: isMobile ? "fixed" : "sticky",
          left: isMobile ? (sidebarOpen ? "0" : "-280px") : "0",
          top: 0,
          height: "100vh",
          transition: "0.3s",
          zIndex: 1000,
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between"
        }}
      >
        <div>
          {/* Logo + toggle */}
          <div
            style={{
              display: "flex",
              justifyContent: sidebarOpen ? "space-between" : "center",
              alignItems: "center",
              marginBottom: "18px"
            }}
          >
            {sidebarOpen ? (
              <div style={{ fontWeight: 800, color: "var(--primary)" }}>
                LMS Pro
              </div>
            ) : (
              <FaGraduationCap />
            )}

            <button
              className="btn btn-secondary"
              onClick={() => setSidebarOpen(!sidebarOpen)}
            >
              <FaBars />
            </button>
          </div>

          {/* Theme toggle */}
          {sidebarOpen && (
            <button
              className="btn btn-primary"
              style={{ width: "100%", marginBottom: "16px" }}
              onClick={() =>
                setTheme(theme === "light" ? "dark" : "light")
              }
            >
              {theme === "light" ? "🌙 Dark" : "☀ Light"}
            </button>
          )}

          {/* Links */}
          {role === "teacher" && (
            <Link to="/teacher-dashboard" style={linkStyle("/teacher-dashboard")}>
              <FaChalkboardTeacher />
              {sidebarOpen && "Dashboard"}
            </Link>
          )}

          {role === "student" && (
            <Link to="/student-dashboard" style={linkStyle("/student-dashboard")}>
              <FaUserGraduate />
              {sidebarOpen && "Dashboard"}
            </Link>
          )}

          <Link to="/courses" style={linkStyle("/courses")}>
            <FaBookOpen />
            {sidebarOpen && "Courses"}
          </Link>

          {role === "student" && (
            <>
              <Link to="/planner" style={linkStyle("/planner")}>
                <FaCalendarAlt />
                {sidebarOpen && "Planner"}
              </Link>

              <Link to="/smart-planner" style={linkStyle("/smart-planner")}>
                <FaBrain />
                {sidebarOpen && "Smart Planner"}
              </Link>

              <Link to="/study-tracker" style={linkStyle("/study-tracker")}>
                <FaClock />
                {sidebarOpen && "Study Tracker"}
              </Link>

              <Link to="/reminders" style={linkStyle("/reminders")}>
                <FaBell />
                {sidebarOpen && "Reminders"}
              </Link>

              <Link to="/student-quiz" style={linkStyle("/student-quiz")}>
                <FaTasks />
                {sidebarOpen && "Quiz"}
              </Link>

              <Link to="/student-assignments" style={linkStyle("/student-assignments")}>
                <FaClipboardList />
                {sidebarOpen && "Assignments"}
              </Link>

              <Link to="/materials" style={linkStyle("/materials")}>
                <FaFolderOpen />
                {sidebarOpen && "Materials"}
              </Link>

              <Link to="/pomodoro" style={linkStyle("/pomodoro")}>
                <FaClock />
                {sidebarOpen && "Pomodoro"}
              </Link>
            </>
          )}

          {role === "teacher" && (
            <>
              <Link to="/teacher-quiz" style={linkStyle("/teacher-quiz")}>
                <FaTasks />
                {sidebarOpen && "Quiz"}
              </Link>

              <Link to="/teacher-assignments" style={linkStyle("/teacher-assignments")}>
                <FaClipboardList />
                {sidebarOpen && "Assignments"}
              </Link>

              <Link to="/upload-material" style={linkStyle("/upload-material")}>
                <FaFolderOpen />
                {sidebarOpen && "Upload"}
              </Link>
            </>
          )}
        </div>

        {/* Logout */}
        <button className="btn btn-danger" onClick={handleLogout}>
          <FaSignOutAlt /> {sidebarOpen && "Logout"}
        </button>
      </aside>

      {/* 🔥 Overlay (mobile only) */}
      {isMobile && sidebarOpen && (
        <div
          onClick={() => setSidebarOpen(false)}
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            width: "100%",
            height: "100vh",
            background: "rgba(0,0,0,0.4)",
            zIndex: 999
          }}
        />
      )}

      {/* 🔥 Main Content */}
      <main style={{ flex: 1 }}>
        {/* Topbar */}
        <div
          style={{
            background: "var(--surface)",
            padding: "14px 18px",
            borderBottom: "1px solid var(--border)",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center"
          }}
        >
          <button
            className="btn btn-primary"
            onClick={() => setSidebarOpen(true)}
          >
            <FaBars />
          </button>

          <div style={{ fontWeight: 700 }}>
            Hello, {userName || "User"}
          </div>
        </div>

        <Outlet />
      </main>
    </div>
  );
}

export default MainLayout;
